-- ============================================================
-- TERRESTRE — STATUS DE PRAZO DE FATURAMENTO
-- Cole este SELECT no painel Administração → campo "Terrestre"
-- ============================================================
-- O UNION ALL original está intacto dentro do CTE BASE.
-- Referência de prazo: DT CONCILIACAO (VDOC.DATACONCILIACAO), não a data de emissão.
-- Identificador da venda: RLOC (PNR.BB_RLOC).
-- Adicionamos DATA_CONCILIACAO_CALC (DATE) em cada parte do UNION.
-- ============================================================

WITH BASE AS (

-- ════════════════════════════════════════════════════════════
-- PARTE 1 — Pré-fatura (FATURADO='S', DOCUMENTO IS NULL)
-- ════════════════════════════════════════════════════════════
SELECT
     CAST(CLI.APELIDO AS VARCHAR(55))                                                                AS CLIENTE
    ,CLI.CODIGO
    ,(SELECT NOMEFANTASIA FROM EMPRESAS WHERE HANDLE = acc.EMPRESA)                                  AS EMPRESA
    ,CASE CON.FREQREG WHEN 1 THEN '01 - DIARIO' WHEN 2 THEN '02 - SEMANAL'
                      WHEN 3 THEN '03 - DECENDIAL' WHEN 4 THEN '04 - QUINZENAL'
                      WHEN 5 THEN '05 - MENSAL'    WHEN 6 THEN '06 - BIMESTRAL' END                 AS PERIODO
    ,(SELECT (CASE K_PONTOATENDIMENTO WHEN 35 THEN 'REEMBOLSO' WHEN 36 THEN 'AUDITORIA' WHEN 33 THEN 'POSTO EMBRAPA' WHEN 27 THEN 'POSTO ITAIPU' WHEN 30 THEN 'POSTO BB' WHEN 3 THEN 'CAIXA' WHEN 4 THEN 'CAIXA BH' WHEN 19 THEN 'POSTO PETROBRAS' WHEN 26 THEN 'POSTO PETROBRAS' WHEN 20 THEN 'POSTO GDF' WHEN 17 THEN 'POSTO MPDG e DERIVADOS' WHEN 28 THEN 'POSTO MPDG e DERIVADOS' WHEN 29 THEN 'POSTO MPDG e DERIVADOS' WHEN 31 THEN 'POSTO MPDG e DERIVADOS' WHEN 32 THEN 'POSTO MPDG e DERIVADOS' WHEN 34 THEN 'POSTO MPDG e DERIVADOS' WHEN 23 THEN 'POSTO BNDES' WHEN 24 THEN 'POSTO FURNAS' ELSE 'DEMAIS CLIENTES' END) FROM BennerSistemaCorporativo..GN_PESSOAS WHERE HANDLE = CLI.HANDLE) AS PONTO_ATENDIMENTO
    ,VDOC.TIPOACCOUNTING                                                                             AS [SITUACAO VENDA]
    ,CONVERT(VARCHAR(12), acc.dataemissao, 103)                                                      AS [DT EMISSAO]
    ,CAST(VDOC.DATACONCILIACAO AS DATE)                                                              AS DATA_CONCILIACAO_CALC
    ,CONVERT(VARCHAR(12), VDOC.DATACONCILIACAO, 103)                                                 AS [DT CONCILIACAO]
    ,CONVERT(VARCHAR(12), VDOC.DATACONCILIACAO, 103)                                                 AS [MES CONCILIACAO]
    ,CONVERT(VARCHAR(12), VDOC.DATAIN,  103)                                                         AS [DATA IN]
    ,CONVERT(VARCHAR(12), VDOC.DATAOUT, 103)                                                         AS [DATA OUT]
    ,ACC.PERMITIRFATURARSEMCONCILIAR
    ,acc.CODIGO                                                                                      AS [COD VENDA]
    ,PNR.BB_RLOC                                                                                     AS RLOC
    ,acc.confirmacao                                                                                  AS CONFIRMACAO
    ,acc.PASSAGEIRONAOCAD                                                                             AS NOME
    ,FORN.APELIDO                                                                                    AS FORNECEDOR
    ,(SELECT CGCCPF FROM GN_PESSOAS WHERE HANDLE = acc.FORNECEDOR)                                   AS CNPJ
    ,ACC.CONSOLIDADOR
    ,acc.tarifa                                                                                      AS [TARIFA ACC]
    ,acc.taxa                                                                                        AS [TAXA ACC]
    ,ACC.OUTRASTAXAS                                                                                 AS [OUTRAS TXS ACC]
    ,ACC.MARKUP                                                                                      AS [MARCKUP ACC]
    ,ACC.EXTRAS
    ,(acc.MANAGEMENTFEE + acc.MANAGEMENTFEEPREVISTO)                                                 AS FEE
    ,(acc.tarifa + acc.taxa + ACC.MARKUP + ACC.EXTRAS)                                               AS [TOTAL ACC]
    ,CASE WHEN ACC.TARIFA > 0 THEN ROUND((acc.TARIFAKANDIR * 100) / ACC.TARIFA, 3) ELSE 0 END       AS [TAR - PERCENTUAL KANDIR]
    ,CASE WHEN ACC.TAXA   > 0 THEN ROUND((acc.TAXA * 100)         / ACC.TAXA,   3) ELSE 0 END       AS [TAX - PERCENTUAL KANDIR]
    ,VDOC.TARIFAKANDIR                                                                               AS [TAR KANDIR - VDOC]
    ,VDOC.TAXAKANDIR                                                                                 AS [TX KANDIR - VDOC]
    ,0                                                                                               AS Faturar
    ,(vdoc.valornominalajustado + vdoc.taxaajustada + vdoc.OUTRASTAXASAJUSTADAS)                    AS Pre
    ,0                                                                                               AS devolvido
    ,(vdoc.valornominalajustado + vdoc.taxaajustada + vdoc.OUTRASTAXASAJUSTADAS)                    AS Total
    ,CASE acc.FORMARECEBIMENTO WHEN 1 THEN 'Cash' WHEN 3 THEN 'Faturado' WHEN 5 THEN 'Cheque' WHEN 6 THEN 'Pagamento Direto' WHEN 7 THEN 'Cartao' WHEN 9 THEN 'Cartao convenio' WHEN 10 THEN 'Sem adicional' WHEN 11 THEN 'Cartao AMEX' WHEN 12 THEN 'Governo' WHEN 13 THEN 'Cheque pre-datado' WHEN 14 THEN 'vendas financiadas por terceiros' WHEN 15 THEN 'multiplos recebimentos' WHEN 16 THEN 'despesas internas' WHEN 17 THEN 'TKT' WHEN 18 THEN 'MCO' WHEN 19 THEN 'Credito reembolso' ELSE 'Nao cadastrado' END AS [FORMA RECEBIMENTO]
    ,CASE acc.FORMADEPAGAMENTO WHEN 1 THEN 'CARTAO' WHEN 2 THEN 'INVOICE' WHEN 3 THEN 'OUTRAS' WHEN 4 THEN 'GR' WHEN 5 THEN 'MULTIPLOS' END AS [FORMA DE PAGAMENTO]
    ,acc.INFMOTIVO                                                                                   AS [Motivo Viagem]
    ,acc.INFOS                                                                                       AS OS
    ,ACC.PROJETO, ACC.REQUISICAOPG, ACC.EMPENHO
    ,CASE WHEN CLI.CODIGO IN ('1536','7512','7561') THEN 'GUSTAVO DEDE' WHEN CLI.CODIGO IN ('107358','20409','1530','1810','103595','1716','1540','1674','1568','1482','11987','7572','1558','1500','107372','107443','1714','1724','1668','24393','7461','1486','183139','160911','7454','1562','28189','1566','7451','280989','934','7453') THEN 'THALES OLIVEIRA' WHEN CLI.CODIGO IN ('1759','7444','1704','1706','1670','1518','2301','7530','9702','1504','1542','1538','1726','1508','3123','7595','1712','7588','1512','1546','7597','1492','1490','7580','1510','7590','7622','123559','7620','7621','1540','3337','389916') THEN 'ALEX PEREIRA' WHEN CLI.CODIGO IN ('1528') THEN 'LEANDRO NUNES' WHEN CLI.CODIGO IN ('1761','1794','151741','12087','12342','12558','12083','12673','12080','12375','9326','12088','11136','12489','11677','12555','12277','12082','13076','12183','12470','12750','12331','12208','7639','12288','7674','12682','12042','12933','12089','12604','255137','12324','12318','2851','2680','3605','2882','3133','1922','2988','5029','12297','2683','3134','2976','1927','2389','186061','2682','2679','2681','12341','7638','11398','12247','12339','12340','12421','13318','13498','14274','255615','1775','11705','460113','473014','446830','288734','460999','1748','1812','460464','474782','9726','2015','1772','2061','7144','7148','7151','264241','1121422') THEN 'RENATO.PEREIRA' WHEN CLI.CODIGO IN ('1524','1718','1742','28942','1758','1720','1722','1678','1769','1698','1684','1690','31458','5246','1682','54','1768','1680','1802') THEN 'LUCAS BRENDO' WHEN CLI.CODIGO IN ('7537','1648','1596','1622','941','1588','1590','1608','1628','1696','1652','1618','1604','1640','1650','1632','1662','1710','1656','1488','1478','1598','107434','1516','1584','1522','1642','9743','1620','1809','1548','7471','1700','1868','1612','1644','2300','1582','1660','1666','1694','1592','1606','1594','1634','1610','1646','1484','1554','1616','1676','1474','1658','1586','1614','1626','1602','472725') THEN 'ERNANDES JUNIOR' WHEN CLI.CODIGO IN ('1526') THEN 'GUILHERME.MELO' WHEN CLI.CODIGO IN ('2487','24527','11599','11920','7152','62389','1894','1944','1820','7593','7468','172616','97375','11776','7153','121770','12274','11720','460086','7146','7150') THEN 'FILIPI.SILVA' WHEN CLI.CODIGO IN ('6116') THEN 'SAMUEL JUNIOR' WHEN CLI.CODIGO IN ('11518','7433','12201','452595','430683','1738','1689','1672','1520','7594','1498','1630','452056','7531') THEN 'PEDRO HENRIQUE' WHEN CLI.CODIGO IN ('1734','1732','1730','1494','1476','474932') THEN 'WELTON.BRITO' WHEN CLI.CODIGO IN ('192750','192746','1767','7439','1793','1801','1780','1797','1818','1736','1744','1766','1774','1764','450807','24483','350315200','35031520','584525990','1750','455142','192762','1752','1746','4170','13917','100760','1584','1806','192146','1690','53','449400','13144','449403','1127346','1816','1788','389916','1763','1795','1777','1775','169411720','455688','1988','2039','1424','58','2034','472785','2006','456905','473253','473241','473252','473248','473238','1664','301879','1805','7584','1800','7584','1807','473246','473236','473250','1765','475568','487291','475275','495460','1963','474787') THEN 'GILMARA.DINO' ELSE 'VERIFICAR' END AS [RESPONSAVEL DOIS]
    ,CASE ACC.PRODUTO WHEN 1 THEN 'BILHETE AEREO' WHEN 2 THEN 'HOTEL' WHEN 3 THEN 'CARRO' WHEN 4 THEN 'MISCELANEOS' WHEN 5 THEN 'PTA' WHEN 6 THEN 'OP' WHEN 7 THEN 'E-TIKET' WHEN 8 THEN 'RODOVIARIO' END AS PRODUTO
    ,(SELECT MAX(tipoaccounting) FROM BennerSistemaCorporativo..bb_vendasdocumentos WHERE accounting = ACC.HANDLE AND ENTRADASAIDA = 'S' AND CONCILIADO = 's') AS [STATUS VENDA]
    ,CASE WHEN (SELECT MAX(tipoaccounting) FROM BennerSistemaCorporativo..bb_vendasdocumentos WHERE accounting = ACC.HANDLE AND ENTRADASAIDA = 'S' AND CONCILIADO = 's') = 'V' THEN 'A Faturar' ELSE 'Verificar' END AS [MOTIVO DEVOLUCAO]
    ,acc.K_observacaofatura                                                                          AS [MOTIVO SUSPENSAO]
    ,CASE WHEN acc.K_observacaofatura IN ('VENDA SEM DOCUMENTO - CARTAO VOETUR','CARTAO - NF VALORES DIVERGENTES','CARTAO - NF INFORMACOES DIVERGENTES','CARTAO - PROBLEMA NO CRE','CARTAO - NF COM CNPJ DIVERGENTE','CARTAO - FALTA DOC COMPLEMENTAR',' CARTAO - NF COM CNPJ DIVERGENTE / VALOR / INFORMACOES','CARTAO - RESERVA CANCELADA','CARTAO - FALTA DOC COMPLEMENTAR ','     CARTAO - NF COM CNPJ DIVERGENTE / VALOR / INFORMACOES','CARTAO - FALTA DECLARAÇÃO OPTANTE') THEN 'Marx Eugênio Gueiros Diniz' WHEN acc.K_observacaofatura IN ('FIEP - AGUARDANDO CHECKOUT','PRIVADOS - AGUARDANDO CHECKOUT') THEN 'Expectativa' WHEN acc.K_observacaofatura IN ('ATENDIMENTO - ANALISE') THEN 'Dalva Regina O. Medeiros de Camargo' WHEN acc.K_observacaofatura IN ('EVENTOS SP - AGUARDANDO LIBERACAO FATURAMENTO') THEN 'Flavia Araujo Galdino' WHEN acc.K_observacaofatura IN ('VENDA CANCELADA - ATENDIMENTO','VENDA COM VALORES DIVERGENTES','VENDA CANCELADA','ERRO NA EMISSAO / ERRO OPERACIONAL','SUSPENSO FATURAMENTO - ANALISE DE DADOS') THEN 'FATURAMENTO' WHEN acc.K_observacaofatura IN ('ANALISE ATENDIMENTO - NO SHOW MERCK') THEN 'Jose Edson Botelho Silva Junior' WHEN acc.K_observacaofatura IN ('FORNECEDOR - AGUARDANDO REEMBOLSO','CON - VENDAS SEM DOCUMENTO','CON -CORRIGIR CONCILIACAO','CON - VALORES DIVERGENTES','CON - DOCUMENTACAO DIVERGENTE','CON - SEM DOC - COMPLEMENTO LOCACAO','CON - LOCACAO MAO DE OBRA','CONCILIAÇÃO E VENDA CANCELADA','CON - SOLICITAR REEMBOLSO FORNECEDOR','VENDA SEM DOCUMENTACAO - TERRESTRE','VENDA COM VALORES DIVERGENTES','CLI - GRUPOS CAIXA','DIVERGENCIA NA DOCUMENTACAO','VENDA EM DUPLICIDADE','FORNECEDOR - CORRIGIR VALOR NOTA FISCAL','CONCILIACAO VALORES DIVERGENTES','FORNECEDOR – Aguardando documentação') THEN 'Conciliação Terrestre / Montanari' WHEN acc.K_observacaofatura IN ('REATIVADO PARA ANALISE FATURAMENTO','REATIVADO PARA INCLUIR MOTIVO') THEN 'FATURAMENTO' ELSE 'VERIFICAR' END AS [ACIONAR O RESPONSAVEL]
FROM BennerSistemaCorporativo..BB_VENDASDOCUMENTOS VDOC
INNER JOIN BennerSistemaCorporativo..BB_PNRACCOUNTINGS ACC   ON ACC.HANDLE = VDOC.ACCOUNTING AND acc.BB_CLIENTE = vdoc.PESSOA
INNER JOIN BennerSistemaCorporativo..BB_PNRS PNR              ON PNR.HANDLE = ACC.RLOC
INNER JOIN BennerSistemaCorporativo..GN_PESSOAS CLI           ON CLI.HANDLE = ACC.BB_CLIENTE
INNER JOIN BennerSistemaCorporativo..GN_PESSOAS FORN          ON FORN.HANDLE = ACC.FORNECEDOR
INNER JOIN BennerSistemaCorporativo..BB_CLIENTECONTRATOS CON  ON CON.PESSOA = ACC.BB_CLIENTE AND ACC.DATAEMISSAO BETWEEN CON.INICIO AND CON.TERMINO AND CON.EMPRESA = ACC.EMPRESA AND (CASE WHEN ACC.EVENTO IS NOT NULL THEN 2 ELSE 1 END) = CON.TIPO
LEFT  JOIN BennerSistemaCorporativo..Z_GRUPOUSUARIOS usu      ON usu.handle = cli.K_FATURISTAAEREO
WHERE (VDOC.VALORNOMINALAJUSTADO <> 0 OR VDOC.TAXAAJUSTADA <> 0)
  AND VDOC.FATURADO = 'S' AND VDOC.DOCUMENTO IS NULL AND VDOC.CANCELADO = 'N'
  AND VDOC.ENTRADASAIDA = 'S' AND VDOC.CONCILIADO = 'S' AND VDOC.TIPODOCUMENTO <> 102
  AND ACC.BB_CLIENTE = VDOC.PESSOA AND ACC.FORMARECEBIMENTO IN (3,8,17,12)
  AND ACC.PRODUTO NOT IN (1,5,6,7) AND VDOC.TIPOACCOUNTING NOT IN ('D','C')

UNION ALL
-- ════════════════════════════════════════════════════════════
-- PARTE 2 — A faturar (FATURADO='N', TIPOACCOUNTING not D/C)
-- ════════════════════════════════════════════════════════════
SELECT
     CAST(CLI.APELIDO AS VARCHAR(55)), CLI.CODIGO
    ,(SELECT NOMEFANTASIA FROM EMPRESAS WHERE HANDLE = acc.EMPRESA)
    ,CASE CON.FREQREG WHEN 1 THEN '01 - DIARIO' WHEN 2 THEN '02 - SEMANAL' WHEN 3 THEN '03 - DECENDIAL' WHEN 4 THEN '04 - QUINZENAL' WHEN 5 THEN '05 - MENSAL' WHEN 6 THEN '06 - BIMESTRAL' END
    ,(SELECT (CASE K_PONTOATENDIMENTO WHEN 35 THEN 'REEMBOLSO' WHEN 36 THEN 'AUDITORIA' WHEN 33 THEN 'POSTO EMBRAPA' WHEN 27 THEN 'POSTO ITAIPU' WHEN 30 THEN 'POSTO BB' WHEN 3 THEN 'CAIXA' WHEN 4 THEN 'CAIXA BH' WHEN 19 THEN 'POSTO PETROBRAS' WHEN 26 THEN 'POSTO PETROBRAS' WHEN 20 THEN 'POSTO GDF' WHEN 17 THEN 'POSTO MPDG e DERIVADOS' WHEN 28 THEN 'POSTO MPDG e DERIVADOS' WHEN 29 THEN 'POSTO MPDG e DERIVADOS' WHEN 31 THEN 'POSTO MPDG e DERIVADOS' WHEN 32 THEN 'POSTO MPDG e DERIVADOS' WHEN 34 THEN 'POSTO MPDG e DERIVADOS' WHEN 23 THEN 'POSTO BNDES' WHEN 24 THEN 'POSTO FURNAS' ELSE 'DEMAIS CLIENTES' END) FROM BennerSistemaCorporativo..GN_PESSOAS WHERE HANDLE = CLI.HANDLE)
    ,VDOC.TIPOACCOUNTING
    ,CONVERT(VARCHAR(12), acc.dataemissao, 103)
    ,CAST(VDOC.DATACONCILIACAO AS DATE)
    ,CONVERT(VARCHAR(12), VDOC.DATACONCILIACAO, 103), CONVERT(VARCHAR(12), VDOC.DATACONCILIACAO, 103)
    ,CONVERT(VARCHAR(12), VDOC.DATAIN, 103), CONVERT(VARCHAR(12), VDOC.DATAOUT, 103)
    ,ACC.PERMITIRFATURARSEMCONCILIAR, acc.CODIGO, PNR.BB_RLOC, acc.confirmacao, acc.PASSAGEIRONAOCAD
    ,FORN.APELIDO, (SELECT CGCCPF FROM GN_PESSOAS WHERE HANDLE = acc.FORNECEDOR), ACC.CONSOLIDADOR
    ,acc.tarifa, acc.taxa, ACC.OUTRASTAXAS, ACC.MARKUP, ACC.EXTRAS
    ,(acc.MANAGEMENTFEE + acc.MANAGEMENTFEEPREVISTO)
    ,(acc.tarifa + acc.taxa + ACC.MARKUP + ACC.EXTRAS)
    ,CASE WHEN ACC.TARIFA > 0 THEN ROUND((acc.TARIFAKANDIR * 100) / ACC.TARIFA, 3) ELSE 0 END
    ,CASE WHEN ACC.TAXA   > 0 THEN ROUND((acc.TAXA * 100) / ACC.TAXA, 3) ELSE 0 END
    ,VDOC.TARIFAKANDIR, VDOC.TAXAKANDIR
    ,(vdoc.valornominalajustado + vdoc.taxaajustada + vdoc.OUTRASTAXASAJUSTADAS), 0, 0
    ,(vdoc.valornominalajustado + vdoc.taxaajustada + vdoc.OUTRASTAXASAJUSTADAS)
    ,CASE acc.FORMARECEBIMENTO WHEN 1 THEN 'Cash' WHEN 3 THEN 'Faturado' WHEN 5 THEN 'Cheque' WHEN 6 THEN 'Pagamento Direto' WHEN 7 THEN 'Cartao' WHEN 9 THEN 'Cartao convenio' WHEN 10 THEN 'Sem adicional' WHEN 11 THEN 'Cartao AMEX' WHEN 12 THEN 'Governo' WHEN 13 THEN 'Cheque pre-datado' WHEN 14 THEN 'vendas financiadas por terceiros' WHEN 15 THEN 'multiplos recebimentos' WHEN 16 THEN 'despesas internas' WHEN 17 THEN 'TKT' WHEN 18 THEN 'MCO' WHEN 19 THEN 'Credito reembolso' ELSE 'Nao cadastrado' END
    ,CASE acc.FORMADEPAGAMENTO WHEN 1 THEN 'CARTAO' WHEN 2 THEN 'INVOICE' WHEN 3 THEN 'OUTRAS' WHEN 4 THEN 'GR' WHEN 5 THEN 'MULTIPLOS' END
    ,acc.INFMOTIVO, acc.INFOS, ACC.PROJETO, ACC.REQUISICAOPG, ACC.EMPENHO
    ,CASE WHEN CLI.CODIGO IN ('1536','7512','7561') THEN 'GUSTAVO DEDE' WHEN CLI.CODIGO IN ('107358','20409','1530','1810','103595','1716','1540','1674','1568','1482','11987','7572','1558','1500','107372','107443','1714','1724','1668','24393','7461','1486','183139','160911','7454','1562','28189','1566','7451','280989','934','7453') THEN 'THALES OLIVEIRA' WHEN CLI.CODIGO IN ('1759','7444','1704','1706','1670','1518','2301','7530','9702','1504','1542','1538','1726','1508','3123','7595','1712','7588','1512','1546','7597','1492','1490','7580','1510','7590','7622','123559','7620','7621','1540','3337','389916') THEN 'ALEX PEREIRA' WHEN CLI.CODIGO IN ('1528') THEN 'LEANDRO NUNES' WHEN CLI.CODIGO IN ('1761','1794','151741','12087','12342','12558','12083','12673','12080','12375','9326','12088','11136','12489','11677','12555','12277','12082','13076','12183','12470','12750','12331','12208','7639','12288','7674','12682','12042','12933','12089','12604','255137','12324','12318','2851','2680','3605','2882','3133','1922','2988','5029','12297','2683','3134','2976','1927','2389','186061','2682','2679','2681','12341','7638','11398','12247','12339','12340','12421','13318','13498','14274','255615','1775','11705','460113','473014','446830','288734','460999','1748','1812','460464','474782','9726','2015','1772','2061','7144','7148','7151','264241','1121422') THEN 'RENATO.PEREIRA' WHEN CLI.CODIGO IN ('1524','1718','1742','28942','1758','1720','1722','1678','1769','1698','1684','1690','31458','5246','1682','54','1768','1680','1802') THEN 'LUCAS BRENDO' WHEN CLI.CODIGO IN ('7537','1648','1596','1622','941','1588','1590','1608','1628','1696','1652','1618','1604','1640','1650','1632','1662','1710','1656','1488','1478','1598','107434','1516','1584','1522','1642','9743','1620','1809','1548','7471','1700','1868','1612','1644','2300','1582','1660','1666','1694','1592','1606','1594','1634','1610','1646','1484','1554','1616','1676','1474','1658','1586','1614','1626','1602','472725') THEN 'ERNANDES JUNIOR' WHEN CLI.CODIGO IN ('1526') THEN 'GUILHERME.MELO' WHEN CLI.CODIGO IN ('2487','24527','11599','11920','7152','62389','1894','1944','1820','7593','7468','172616','97375','11776','7153','121770','12274','11720','460086','7146','7150') THEN 'FILIPI.SILVA' WHEN CLI.CODIGO IN ('6116') THEN 'SAMUEL JUNIOR' WHEN CLI.CODIGO IN ('11518','7433','12201','452595','430683','1738','1689','1672','1520','7594','1498','1630','452056','7531') THEN 'PEDRO HENRIQUE' WHEN CLI.CODIGO IN ('1734','1732','1730','1494','1476','474932') THEN 'WELTON.BRITO' WHEN CLI.CODIGO IN ('192750','192746','1767','7439','1793','1801','1780','1797','1818','1736','1744','1766','1774','1764','450807','24483','350315200','35031520','584525990','1750','455142','192762','1752','1746','4170','13917','100760','1584','1806','192146','1690','53','449400','13144','449403','1127346','1816','1788','389916','1763','1795','1777','1775','169411720','455688','1988','2039','1424','58','2034','472785','2006','456905','473253','473241','473252','473248','473238','1664','301879','1805','7584','1800','7584','1807','473246','473236','473250','1765','475568','487291','475275','495460','1963','474787') THEN 'GILMARA.DINO' ELSE 'VERIFICAR' END
    ,CASE ACC.PRODUTO WHEN 1 THEN 'BILHETE AEREO' WHEN 2 THEN 'HOTEL' WHEN 3 THEN 'CARRO' WHEN 4 THEN 'MISCELANEOS' WHEN 5 THEN 'PTA' WHEN 6 THEN 'OP' WHEN 7 THEN 'E-TIKET' WHEN 8 THEN 'RODOVIARIO' END
    ,(SELECT MAX(tipoaccounting) FROM BennerSistemaCorporativo..bb_vendasdocumentos WHERE accounting = ACC.HANDLE AND ENTRADASAIDA = 'S' AND CONCILIADO = 's')
    ,CASE WHEN (SELECT MAX(tipoaccounting) FROM BennerSistemaCorporativo..bb_vendasdocumentos WHERE accounting = ACC.HANDLE AND ENTRADASAIDA = 'S' AND CONCILIADO = 's') = 'V' THEN 'A Faturar' ELSE 'Verificar' END
    ,acc.K_observacaofatura
    ,CASE WHEN acc.K_observacaofatura IN ('VENDA SEM DOCUMENTO - CARTAO VOETUR','CARTAO - NF VALORES DIVERGENTES','CARTAO - NF INFORMACOES DIVERGENTES','CARTAO - PROBLEMA NO CRE','CARTAO - NF COM CNPJ DIVERGENTE','CARTAO - FALTA DOC COMPLEMENTAR',' CARTAO - NF COM CNPJ DIVERGENTE / VALOR / INFORMACOES','CARTAO - RESERVA CANCELADA','CARTAO - FALTA DOC COMPLEMENTAR ','     CARTAO - NF COM CNPJ DIVERGENTE / VALOR / INFORMACOES','CARTAO - FALTA DECLARAÇÃO OPTANTE') THEN 'Marx Eugênio Gueiros Diniz' WHEN acc.K_observacaofatura IN ('FIEP - AGUARDANDO CHECKOUT','PRIVADOS - AGUARDANDO CHECKOUT') THEN 'Expectativa' WHEN acc.K_observacaofatura IN ('ATENDIMENTO - ANALISE') THEN 'Dalva Regina O. Medeiros de Camargo' WHEN acc.K_observacaofatura IN ('EVENTOS SP - AGUARDANDO LIBERACAO FATURAMENTO') THEN 'Flavia Araujo Galdino' WHEN acc.K_observacaofatura IN ('VENDA CANCELADA - ATENDIMENTO','VENDA COM VALORES DIVERGENTES','VENDA CANCELADA','ERRO NA EMISSAO / ERRO OPERACIONAL','SUSPENSO FATURAMENTO - ANALISE DE DADOS') THEN 'FATURAMENTO' WHEN acc.K_observacaofatura IN ('ANALISE ATENDIMENTO - NO SHOW MERCK') THEN 'Jose Edson Botelho Silva Junior' WHEN acc.K_observacaofatura IN ('FORNECEDOR - AGUARDANDO REEMBOLSO','CON - VENDAS SEM DOCUMENTO','CON -CORRIGIR CONCILIACAO','CON - VALORES DIVERGENTES','CON - DOCUMENTACAO DIVERGENTE','CON - SEM DOC - COMPLEMENTO LOCACAO','CON - LOCACAO MAO DE OBRA','CONCILIAÇÃO E VENDA CANCELADA','CON - SOLICITAR REEMBOLSO FORNECEDOR','VENDA SEM DOCUMENTACAO - TERRESTRE','VENDA COM VALORES DIVERGENTES','CLI - GRUPOS CAIXA','DIVERGENCIA NA DOCUMENTACAO','VENDA EM DUPLICIDADE','FORNECEDOR - CORRIGIR VALOR NOTA FISCAL','CONCILIACAO VALORES DIVERGENTES','FORNECEDOR – Aguardando documentação') THEN 'Conciliação Terrestre / Montanari' WHEN acc.K_observacaofatura IN ('REATIVADO PARA ANALISE FATURAMENTO','REATIVADO PARA INCLUIR MOTIVO') THEN 'FATURAMENTO' ELSE 'VERIFICAR' END
FROM BennerSistemaCorporativo..BB_VENDASDOCUMENTOS VDOC
INNER JOIN BennerSistemaCorporativo..BB_PNRACCOUNTINGS ACC   ON ACC.HANDLE = VDOC.ACCOUNTING AND acc.BB_CLIENTE = vdoc.PESSOA
INNER JOIN BennerSistemaCorporativo..BB_PNRS PNR              ON PNR.HANDLE = ACC.RLOC
INNER JOIN BennerSistemaCorporativo..GN_PESSOAS CLI           ON CLI.HANDLE = ACC.BB_CLIENTE
INNER JOIN BennerSistemaCorporativo..GN_PESSOAS FORN          ON FORN.HANDLE = ACC.FORNECEDOR
INNER JOIN BennerSistemaCorporativo..BB_CLIENTECONTRATOS CON  ON CON.PESSOA = ACC.BB_CLIENTE AND ACC.DATAEMISSAO BETWEEN CON.INICIO AND CON.TERMINO AND CON.EMPRESA = ACC.EMPRESA AND (CASE WHEN ACC.EVENTO IS NOT NULL THEN 2 ELSE 1 END) = CON.TIPO
LEFT  JOIN BennerSistemaCorporativo..Z_GRUPOUSUARIOS usu      ON usu.handle = cli.K_FATURISTAAEREO
WHERE (VDOC.VALORNOMINALAJUSTADO <> 0 OR VDOC.TAXAAJUSTADA <> 0)
  AND VDOC.FATURADO = 'N' AND VDOC.CANCELADO = 'N' AND ACC.SITUACAO = 1
  AND VDOC.ENTRADASAIDA = 'S' AND VDOC.CONCILIADO = 'S' AND VDOC.TIPODOCUMENTO <> 102
  AND ACC.BB_CLIENTE = VDOC.PESSOA AND ACC.FORMARECEBIMENTO IN (3,8,17,12)
  AND ACC.PRODUTO NOT IN (1,5,6,7) AND VDOC.TIPOACCOUNTING NOT IN ('D','C')

UNION ALL
-- ════════════════════════════════════════════════════════════
-- PARTE 3 — Devolvidos (FATURADO='N', TIPOACCOUNTING='D')
-- ════════════════════════════════════════════════════════════
SELECT
     CAST(CLI.APELIDO AS VARCHAR(55)), CLI.CODIGO
    ,(SELECT NOMEFANTASIA FROM EMPRESAS WHERE HANDLE = acc.EMPRESA)
    ,CASE CON.FREQREG WHEN 1 THEN '01 - DIARIO' WHEN 2 THEN '02 - SEMANAL' WHEN 3 THEN '03 - DECENDIAL' WHEN 4 THEN '04 - QUINZENAL' WHEN 5 THEN '05 - MENSAL' WHEN 6 THEN '06 - BIMESTRAL' END
    ,(SELECT (CASE K_PONTOATENDIMENTO WHEN 35 THEN 'REEMBOLSO' WHEN 36 THEN 'AUDITORIA' WHEN 33 THEN 'POSTO EMBRAPA' WHEN 27 THEN 'POSTO ITAIPU' WHEN 30 THEN 'POSTO BB' WHEN 3 THEN 'CAIXA' WHEN 4 THEN 'CAIXA BH' WHEN 19 THEN 'POSTO PETROBRAS' WHEN 26 THEN 'POSTO PETROBRAS' WHEN 20 THEN 'POSTO GDF' WHEN 17 THEN 'POSTO MPDG e DERIVADOS' WHEN 28 THEN 'POSTO MPDG e DERIVADOS' WHEN 29 THEN 'POSTO MPDG e DERIVADOS' WHEN 31 THEN 'POSTO MPDG e DERIVADOS' WHEN 32 THEN 'POSTO MPDG e DERIVADOS' WHEN 34 THEN 'POSTO MPDG e DERIVADOS' WHEN 23 THEN 'POSTO BNDES' WHEN 24 THEN 'POSTO FURNAS' ELSE 'DEMAIS CLIENTES' END) FROM BennerSistemaCorporativo..GN_PESSOAS WHERE HANDLE = CLI.HANDLE)
    ,VDOC.TIPOACCOUNTING
    ,CONVERT(VARCHAR(12), acc.dataemissao, 103)
    ,CAST(VDOC.DATACONCILIACAO AS DATE)
    ,CONVERT(VARCHAR(12), VDOC.DATACONCILIACAO, 103), CONVERT(VARCHAR(12), VDOC.DATACONCILIACAO, 103)
    ,CONVERT(VARCHAR(12), VDOC.DATAIN, 103), CONVERT(VARCHAR(12), VDOC.DATAOUT, 103)
    ,ACC.PERMITIRFATURARSEMCONCILIAR, acc.CODIGO, PNR.BB_RLOC, acc.confirmacao, acc.PASSAGEIRONAOCAD
    ,FORN.APELIDO, (SELECT CGCCPF FROM GN_PESSOAS WHERE HANDLE = acc.FORNECEDOR), ACC.CONSOLIDADOR
    ,acc.tarifa, acc.taxa, ACC.OUTRASTAXAS, ACC.MARKUP, ACC.EXTRAS
    ,(acc.MANAGEMENTFEE + acc.MANAGEMENTFEEPREVISTO)
    ,(acc.tarifa + acc.taxa + ACC.MARKUP + ACC.EXTRAS)
    ,CASE WHEN ACC.TARIFA > 0 THEN ROUND((acc.TARIFAKANDIR * 100) / ACC.TARIFA, 3) ELSE 0 END
    ,CASE WHEN ACC.TAXA   > 0 THEN ROUND((acc.TAXA * 100) / ACC.TAXA, 3) ELSE 0 END
    ,VDOC.TARIFAKANDIR, VDOC.TAXAKANDIR
    ,0, 0
    ,(vdoc.valornominalajustado + vdoc.taxaajustada + vdoc.OUTRASTAXASAJUSTADAS)
    ,(vdoc.valornominalajustado + vdoc.taxaajustada + vdoc.OUTRASTAXASAJUSTADAS)
    ,CASE acc.FORMARECEBIMENTO WHEN 1 THEN 'Cash' WHEN 3 THEN 'Faturado' WHEN 5 THEN 'Cheque' WHEN 6 THEN 'Pagamento Direto' WHEN 7 THEN 'Cartao' WHEN 9 THEN 'Cartao convenio' WHEN 10 THEN 'Sem adicional' WHEN 11 THEN 'Cartao AMEX' WHEN 12 THEN 'Governo' WHEN 13 THEN 'Cheque pre-datado' WHEN 14 THEN 'vendas financiadas por terceiros' WHEN 15 THEN 'multiplos recebimentos' WHEN 16 THEN 'despesas internas' WHEN 17 THEN 'TKT' WHEN 18 THEN 'MCO' WHEN 19 THEN 'Credito reembolso' ELSE 'Nao cadastrado' END
    ,CASE acc.FORMADEPAGAMENTO WHEN 1 THEN 'CARTAO' WHEN 2 THEN 'INVOICE' WHEN 3 THEN 'OUTRAS' WHEN 4 THEN 'GR' WHEN 5 THEN 'MULTIPLOS' END
    ,acc.INFMOTIVO, acc.INFOS, ACC.PROJETO, ACC.REQUISICAOPG, ACC.EMPENHO
    ,CASE WHEN CLI.CODIGO IN ('1536','7512','7561') THEN 'GUSTAVO DEDE' WHEN CLI.CODIGO IN ('107358','20409','1530','1810','103595','1716','1540','1674','1568','1482','11987','7572','1558','1500','107372','107443','1714','1724','1668','24393','7461','1486','183139','160911','7454','1562','28189','1566','7451','280989','934','7453') THEN 'THALES OLIVEIRA' WHEN CLI.CODIGO IN ('1759','7444','1704','1706','1670','1518','2301','7530','9702','1504','1542','1538','1726','1508','3123','7595','1712','7588','1512','1546','7597','1492','1490','7580','1510','7590','7622','123559','7620','7621','1540','3337','389916') THEN 'ALEX PEREIRA' WHEN CLI.CODIGO IN ('1528') THEN 'LEANDRO NUNES' WHEN CLI.CODIGO IN ('1761','1794','151741','12087','12342','12558','12083','12673','12080','12375','9326','12088','11136','12489','11677','12555','12277','12082','13076','12183','12470','12750','12331','12208','7639','12288','7674','12682','12042','12933','12089','12604','255137','12324','12318','2851','2680','3605','2882','3133','1922','2988','5029','12297','2683','3134','2976','1927','2389','186061','2682','2679','2681','12341','7638','11398','12247','12339','12340','12421','13318','13498','14274','255615','1775','11705','460113','473014','446830','288734','460999','1748','1812','460464','474782','9726','2015','1772','2061','7144','7148','7151','264241','1121422') THEN 'RENATO.PEREIRA' WHEN CLI.CODIGO IN ('1524','1718','1742','28942','1758','1720','1722','1678','1769','1698','1684','1690','31458','5246','1682','54','1768','1680','1802') THEN 'LUCAS BRENDO' WHEN CLI.CODIGO IN ('7537','1648','1596','1622','941','1588','1590','1608','1628','1696','1652','1618','1604','1640','1650','1632','1662','1710','1656','1488','1478','1598','107434','1516','1584','1522','1642','9743','1620','1809','1548','7471','1700','1868','1612','1644','2300','1582','1660','1666','1694','1592','1606','1594','1634','1610','1646','1484','1554','1616','1676','1474','1658','1586','1614','1626','1602','472725') THEN 'ERNANDES JUNIOR' WHEN CLI.CODIGO IN ('1526') THEN 'GUILHERME.MELO' WHEN CLI.CODIGO IN ('2487','24527','11599','11920','7152','62389','1894','1944','1820','7593','7468','172616','97375','11776','7153','121770','12274','11720','460086','7146','7150') THEN 'FILIPI.SILVA' WHEN CLI.CODIGO IN ('6116') THEN 'SAMUEL JUNIOR' WHEN CLI.CODIGO IN ('11518','7433','12201','452595','430683','1738','1689','1672','1520','7594','1498','1630','452056','7531') THEN 'PEDRO HENRIQUE' WHEN CLI.CODIGO IN ('1734','1732','1730','1494','1476','474932') THEN 'WELTON.BRITO' WHEN CLI.CODIGO IN ('192750','192746','1767','7439','1793','1801','1780','1797','1818','1736','1744','1766','1774','1764','450807','24483','350315200','35031520','584525990','1750','455142','192762','1752','1746','4170','13917','100760','1584','1806','192146','1690','53','449400','13144','449403','1127346','1816','1788','389916','1763','1795','1777','1775','169411720','455688','1988','2039','1424','58','2034','472785','2006','456905','473253','473241','473252','473248','473238','1664','301879','1805','7584','1800','7584','1807','473246','473236','473250','1765','475568','487291','475275','495460','1963','474787') THEN 'GILMARA.DINO' ELSE 'VERIFICAR' END
    ,CASE ACC.PRODUTO WHEN 1 THEN 'BILHETE AEREO' WHEN 2 THEN 'HOTEL' WHEN 3 THEN 'CARRO' WHEN 4 THEN 'MISCELANEOS' WHEN 5 THEN 'PTA' WHEN 6 THEN 'OP' WHEN 7 THEN 'E-TIKET' WHEN 8 THEN 'RODOVIARIO' END
    ,(SELECT MAX(tipoaccounting) FROM BennerSistemaCorporativo..bb_vendasdocumentos WHERE accounting = ACC.HANDLE AND ENTRADASAIDA = 'S' AND CONCILIADO = 's')
    ,CASE WHEN (SELECT MAX(tipoaccounting) FROM BennerSistemaCorporativo..bb_vendasdocumentos WHERE accounting = ACC.HANDLE AND ENTRADASAIDA = 'S' AND CONCILIADO = 's') = 'V' THEN 'A Faturar' ELSE 'Verificar' END
    ,acc.K_observacaofatura
    ,CASE WHEN acc.K_observacaofatura IN ('VENDA SEM DOCUMENTO - CARTAO VOETUR','CARTAO - NF VALORES DIVERGENTES','CARTAO - NF INFORMACOES DIVERGENTES','CARTAO - PROBLEMA NO CRE','CARTAO - NF COM CNPJ DIVERGENTE','CARTAO - FALTA DOC COMPLEMENTAR',' CARTAO - NF COM CNPJ DIVERGENTE / VALOR / INFORMACOES','CARTAO - RESERVA CANCELADA','CARTAO - FALTA DOC COMPLEMENTAR ','     CARTAO - NF COM CNPJ DIVERGENTE / VALOR / INFORMACOES','CARTAO - FALTA DECLARAÇÃO OPTANTE') THEN 'Marx Eugênio Gueiros Diniz' WHEN acc.K_observacaofatura IN ('FIEP - AGUARDANDO CHECKOUT','PRIVADOS - AGUARDANDO CHECKOUT') THEN 'Expectativa' WHEN acc.K_observacaofatura IN ('ATENDIMENTO - ANALISE') THEN 'Dalva Regina O. Medeiros de Camargo' WHEN acc.K_observacaofatura IN ('EVENTOS SP - AGUARDANDO LIBERACAO FATURAMENTO') THEN 'Flavia Araujo Galdino' WHEN acc.K_observacaofatura IN ('VENDA CANCELADA - ATENDIMENTO','VENDA COM VALORES DIVERGENTES','VENDA CANCELADA','ERRO NA EMISSAO / ERRO OPERACIONAL','SUSPENSO FATURAMENTO - ANALISE DE DADOS') THEN 'FATURAMENTO' WHEN acc.K_observacaofatura IN ('ANALISE ATENDIMENTO - NO SHOW MERCK') THEN 'Jose Edson Botelho Silva Junior' WHEN acc.K_observacaofatura IN ('FORNECEDOR - AGUARDANDO REEMBOLSO','CON - VENDAS SEM DOCUMENTO','CON -CORRIGIR CONCILIACAO','CON - VALORES DIVERGENTES','CON - DOCUMENTACAO DIVERGENTE','CON - SEM DOC - COMPLEMENTO LOCACAO','CON - LOCACAO MAO DE OBRA','CONCILIAÇÃO E VENDA CANCELADA','CON - SOLICITAR REEMBOLSO FORNECEDOR','VENDA SEM DOCUMENTACAO - TERRESTRE','VENDA COM VALORES DIVERGENTES','CLI - GRUPOS CAIXA','DIVERGENCIA NA DOCUMENTACAO','VENDA EM DUPLICIDADE','FORNECEDOR - CORRIGIR VALOR NOTA FISCAL','CONCILIACAO VALORES DIVERGENTES','FORNECEDOR – Aguardando documentação') THEN 'Conciliação Terrestre / Montanari' WHEN acc.K_observacaofatura IN ('REATIVADO PARA ANALISE FATURAMENTO','REATIVADO PARA INCLUIR MOTIVO') THEN 'FATURAMENTO' ELSE 'VERIFICAR' END
FROM BennerSistemaCorporativo..BB_VENDASDOCUMENTOS VDOC
INNER JOIN BennerSistemaCorporativo..BB_PNRACCOUNTINGS ACC   ON ACC.HANDLE = VDOC.ACCOUNTING AND acc.BB_CLIENTE = vdoc.PESSOA
INNER JOIN BennerSistemaCorporativo..BB_PNRS PNR              ON PNR.HANDLE = ACC.RLOC
INNER JOIN BennerSistemaCorporativo..GN_PESSOAS CLI           ON CLI.HANDLE = ACC.BB_CLIENTE
INNER JOIN BennerSistemaCorporativo..GN_PESSOAS FORN          ON FORN.HANDLE = ACC.FORNECEDOR
INNER JOIN BennerSistemaCorporativo..BB_CLIENTECONTRATOS CON  ON CON.PESSOA = ACC.BB_CLIENTE AND ACC.DATAEMISSAO BETWEEN CON.INICIO AND CON.TERMINO AND CON.EMPRESA = ACC.EMPRESA AND (CASE WHEN ACC.EVENTO IS NOT NULL THEN 2 ELSE 1 END) = CON.TIPO
LEFT  JOIN BennerSistemaCorporativo..Z_GRUPOUSUARIOS usu      ON usu.handle = cli.K_FATURISTAAEREO
WHERE (VDOC.VALORNOMINALAJUSTADO <> 0 OR VDOC.TAXAAJUSTADA <> 0)
  AND VDOC.FATURADO = 'N' AND VDOC.CANCELADO = 'N' AND ACC.SITUACAO = 1
  AND VDOC.ENTRADASAIDA = 'S' AND VDOC.CONCILIADO = 'S' AND VDOC.TIPODOCUMENTO <> 102
  AND ACC.BB_CLIENTE = VDOC.PESSOA AND ACC.FORMARECEBIMENTO IN (3,8,17,12)
  AND ACC.PRODUTO NOT IN (1,5,6,7) AND VDOC.TIPOACCOUNTING IN ('D')

), -- fim BASE

-- ── Calcula os limites do período usando DATA_CONCILIACAO_CALC e PERIODO ──────
PERIODOS AS (
    SELECT *,
        CAST(GETDATE() AS DATE) AS DATA_ATUAL,
        CASE LEFT(PERIODO, 2)
            WHEN '01' THEN 'DIARIO'    WHEN '02' THEN 'SEMANAL'
            WHEN '03' THEN 'DECENDIAL' WHEN '04' THEN 'QUINZENAL'
            WHEN '05' THEN 'MENSAL'    ELSE NULL
        END AS PERIODICIDADE,
        CASE LEFT(PERIODO, 2)
            WHEN '01' THEN DATA_CONCILIACAO_CALC
            WHEN '02' THEN CASE WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN  1 AND  7 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC), 1) WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN  8 AND 14 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC), 8) WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN 15 AND 21 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),15) ELSE DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),22) END
            WHEN '03' THEN CASE WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN  1 AND 10 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC), 1) WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN 11 AND 20 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),11) ELSE DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),21) END
            WHEN '04' THEN CASE WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN 1 AND 15 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC), 1) ELSE DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),16) END
            WHEN '05' THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),1)
            ELSE NULL
        END AS DATA_INICIO_PERIODO,
        CASE LEFT(PERIODO, 2)
            WHEN '01' THEN DATA_CONCILIACAO_CALC
            WHEN '02' THEN CASE WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN  1 AND  7 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC), 7) WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN  8 AND 14 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),14) WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN 15 AND 21 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),21) ELSE EOMONTH(DATA_CONCILIACAO_CALC) END
            WHEN '03' THEN CASE WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN  1 AND 10 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),10) WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN 11 AND 20 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),20) ELSE EOMONTH(DATA_CONCILIACAO_CALC) END
            WHEN '04' THEN CASE WHEN DAY(DATA_CONCILIACAO_CALC) BETWEEN 1 AND 15 THEN DATEFROMPARTS(YEAR(DATA_CONCILIACAO_CALC),MONTH(DATA_CONCILIACAO_CALC),15) ELSE EOMONTH(DATA_CONCILIACAO_CALC) END
            WHEN '05' THEN EOMONTH(DATA_CONCILIACAO_CALC)
            ELSE NULL
        END AS DATA_FIM_PERIODO,
        -- Data de referência para clientes especiais: DT RELATORIO > DT CONCILIACAO > DT EMISSAO
        COALESCE(
            TRY_CONVERT(DATE, [DT RELATORIO], 103),
            DATA_CONCILIACAO_CALC,
            TRY_CONVERT(DATE, [DT EMISSAO], 103)
        ) AS DATA_REF_CALC
    FROM BASE
)

-- ── SELECT FINAL ─────────────────────────────────────────────────────────────
SELECT
    *,
    CASE [RESPONSAVEL DOIS]
        WHEN 'GILMARA.DINO'   THEN 'FATURAMENTO - SAO PAULO'
        WHEN 'RENATO.PEREIRA' THEN 'FATURAMENTO - SAO PAULO'
        ELSE 'FATURAMENTO - BRASILIA'
    END AS [FILIAL DE FATURAMENTO],
    CASE
        WHEN DATA_CONCILIACAO_CALC IS NULL OR PERIODICIDADE IS NULL OR DATA_FIM_PERIODO IS NULL THEN NULL
        WHEN DATA_ATUAL <= DATA_FIM_PERIODO THEN 0
        ELSE DATEDIFF(DAY, DATA_FIM_PERIODO, DATA_ATUAL)
    END AS DIAS_EM_ATRASO,
    -- Clientes com ciclo de faturamento personalizado sobrepõem a regra geral do contrato
    CASE
        WHEN CODIGO = '1526' THEN  -- PETROBRAS: ciclo 26/M a 25/M+1 (hoje>=26) ou 26/M-1 a 25/M (hoje<26) | ref: DT RELATORIO > DT CONCILIACAO > DT EMISSAO
            CASE
                WHEN DATA_REF_CALC IS NULL THEN 'NÃO CLASSIFICADO'
                WHEN DATA_REF_CALC BETWEEN
                    CASE WHEN DAY(DATA_ATUAL) >= 26
                         THEN DATEFROMPARTS(YEAR(DATA_ATUAL), MONTH(DATA_ATUAL), 26)
                         ELSE DATEFROMPARTS(YEAR(DATEADD(MONTH,-1,DATA_ATUAL)), MONTH(DATEADD(MONTH,-1,DATA_ATUAL)), 26) END
                    AND
                    CASE WHEN DAY(DATA_ATUAL) >= 26
                         THEN DATEFROMPARTS(YEAR(DATEADD(MONTH,1,DATA_ATUAL)), MONTH(DATEADD(MONTH,1,DATA_ATUAL)), 25)
                         ELSE DATEFROMPARTS(YEAR(DATA_ATUAL), MONTH(DATA_ATUAL), 25) END
                THEN 'DENTRO DO PRAZO' ELSE 'FORA DO PRAZO'
            END
        WHEN CODIGO = '1530' THEN  -- AG PLANALTO DF: ciclo 21/M a 20/M+1 (hoje>=21) ou 21/M-1 a 20/M (hoje<21) | ref: DT RELATORIO > DT CONCILIACAO > DT EMISSAO
            CASE
                WHEN DATA_REF_CALC IS NULL THEN 'NÃO CLASSIFICADO'
                WHEN DATA_REF_CALC BETWEEN
                    CASE WHEN DAY(DATA_ATUAL) >= 21
                         THEN DATEFROMPARTS(YEAR(DATA_ATUAL), MONTH(DATA_ATUAL), 21)
                         ELSE DATEFROMPARTS(YEAR(DATEADD(MONTH,-1,DATA_ATUAL)), MONTH(DATEADD(MONTH,-1,DATA_ATUAL)), 21) END
                    AND
                    CASE WHEN DAY(DATA_ATUAL) >= 21
                         THEN DATEFROMPARTS(YEAR(DATEADD(MONTH,1,DATA_ATUAL)), MONTH(DATEADD(MONTH,1,DATA_ATUAL)), 20)
                         ELSE DATEFROMPARTS(YEAR(DATA_ATUAL), MONTH(DATA_ATUAL), 20) END
                THEN 'DENTRO DO PRAZO' ELSE 'FORA DO PRAZO'
            END
        WHEN CODIGO = '1486' THEN  -- MRE DIVISAO DO PESSOAL: ciclo 14/M a 13/M+1 (hoje>=14) ou 14/M-1 a 13/M (hoje<14) | ref: DT RELATORIO > DT CONCILIACAO > DT EMISSAO
            CASE
                WHEN DATA_REF_CALC IS NULL THEN 'NÃO CLASSIFICADO'
                WHEN DATA_REF_CALC BETWEEN
                    CASE WHEN DAY(DATA_ATUAL) >= 14
                         THEN DATEFROMPARTS(YEAR(DATA_ATUAL), MONTH(DATA_ATUAL), 14)
                         ELSE DATEFROMPARTS(YEAR(DATEADD(MONTH,-1,DATA_ATUAL)), MONTH(DATEADD(MONTH,-1,DATA_ATUAL)), 14) END
                    AND
                    CASE WHEN DAY(DATA_ATUAL) >= 14
                         THEN DATEFROMPARTS(YEAR(DATEADD(MONTH,1,DATA_ATUAL)), MONTH(DATEADD(MONTH,1,DATA_ATUAL)), 13)
                         ELSE DATEFROMPARTS(YEAR(DATA_ATUAL), MONTH(DATA_ATUAL), 13) END
                THEN 'DENTRO DO PRAZO' ELSE 'FORA DO PRAZO'
            END
        WHEN DATA_CONCILIACAO_CALC IS NULL THEN 'NÃO CLASSIFICADO'
        WHEN PERIODICIDADE     IS NULL THEN 'NÃO CLASSIFICADO'
        WHEN DATA_FIM_PERIODO  IS NULL THEN 'NÃO CLASSIFICADO'
        WHEN DATA_ATUAL <= DATA_FIM_PERIODO THEN 'DENTRO DO PRAZO'
        ELSE 'FORA DO PRAZO'
    END AS STATUS_PRAZO,
    CASE
        WHEN DATA_CONCILIACAO_CALC IS NULL THEN 'Data de conciliação não informada'
        WHEN PERIODO           IS NULL THEN 'Contrato/período não encontrado para o cliente'
        WHEN PERIODICIDADE     IS NULL THEN 'Periodicidade não suportada: ' + ISNULL(PERIODO, '')
        ELSE NULL
    END AS MOTIVO_NAO_CLASSIFICADO
FROM PERIODOS
